SELECT t.id || ' — требования видны на экранах, а поля «Экраны» нет' AS detail FROM project_plan_tasks t WHERE t.project_id = $1 AND t.kind = 'dev' AND EXISTS (SELECT 1 FROM task_requirement tr JOIN project_screen_requirements sr ON sr.project_id = tr.project_id AND sr.requirement_id = tr.requirement_id WHERE tr.project_id = t.project_id AND tr.task_id = t.id) AND NOT EXISTS (SELECT 1 FROM project_document_fields f WHERE f.project_id = t.project_id AND f.entity_kind = 'task' AND f.entity_name = t.entity_name AND f.name = 'Экраны') ORDER BY 1
